  ('0558538a-9dc7-525d-aaeb-f055c41f816a', null, (select id from public.skills where slug = 'write-g10-sentence-structure'), null, 'medium',
   $q$Read the sentence: "The bridge was designed to sway slightly in strong winds ___ engineers were not alarmed by the movement." Which choice correctly completes the sentence?$q$, $q$[{"text":", therefore;","is_correct":false,"misconception_token":"semicolon-misplaced"},{"text":" therefore,","is_correct":false,"misconception_token":"fused-sentence"},{"text":", therefore,","is_correct":false,"misconception_token":"conjunctive-adverb-with-comma-only"},{"text":"; therefore,","is_correct":true}]$q$::jsonb, $q$; therefore,$q$, $q$"Therefore" is a conjunctive adverb, so it needs a semicolon before it when it joins two independent clauses, with a comma after it. Using only commas around "therefore" leaves a comma splice.$q$, 'draft', null)
