  ('8e19ecda-dc2c-5935-aae1-ff24a6592344', null, (select id from public.skills where slug = 'write-g11-informative-writing'), null, 'hard',
   $q$Why is it effective for the writer to place paragraph 2 (sentences 4 to 7) before the paragraphs about cold storage and copying?$q$, $q$[{"text":"The paragraphs are arranged in the order in which archives were built.","is_correct":false,"misconception_token":"misidentifies-structure"},{"text":"Paragraph 2 is the most interesting part, so it should come early.","is_correct":false,"misconception_token":"appeal-not-logic"},{"text":"Paragraph 2 disproves the claim made in paragraph 1.","is_correct":false,"misconception_token":"misreads-relationship"},{"text":"Readers need to understand how nitrate decays before they can see why cold storage and copying are necessary.","is_correct":true}]$q$::jsonb, $q$Readers need to understand how nitrate decays before they can see why cold storage and copying are necessary.$q$, $q$Each later paragraph responds to the decay described in paragraph 2, so that paragraph must come first for the ideas to build. The report never orders paragraphs by when archives were built.$q$, 'draft', 'f2f16490-877e-5795-bcc8-8881e3af32e0')
